entries[463071] = { ["name"] = "Blutiger Überschuss", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Phiole mit Schwarzblut zerbricht und verschüttet ihren Inhalt, wodurch eine Lache entsteht, die alle 0.5 Sek. 230253 Schattenschaden verursacht und die nächsten 490734 von Spielercharakteren innerhalb des Effektbereichs erhaltene Heilung absorbiert.\n\nEier, die mit der Lache in Berührung kommen, setzen schreckliche Kreaturen frei, die Spielercharaktere angreifen." }
entries[463073] = { ["name"] = "Avatar der Sonne", ["text"] = "100 Meter Reichweite\nSofort\nVergeltung\nWährend 'Zornige Vergeltung' aktiv ist, werdet Ihr mit Euren Instanzen von 'Morgenlicht' innerhalb von 30 Metern verbunden, wodurch Gegner (21.6% der Zaubermacht) Strahlenschaden erleiden bzw. Verbündete um (18.63% der Zaubermacht) Gesundheit geheilt werden, wenn sie durch die Strahlen laufen. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert.\n\nDas Aktivieren von ['Zornige Vergeltung' belegt Verbündete oder Gegner in der Nähe mit bis zu 2 Stapeln 'Morgenlicht']['Zornige Vergeltung' belegt Verbündete oder Gegner in der Nähe mit bis zu 4 Stapeln 'Morgenlicht'] und erhöht die Dauer von 'Morgenlicht' um 20%.\n\nHeilig, Heilig (Zornige Vergeltung)\nWährend 'Zornige Vergeltung' aktiv ist, werdet Ihr mit Euren Instanzen von 'Morgenlicht' innerhalb von 30 Metern verbunden, wodurch Gegner (21.6% der Zaubermacht) Strahlenschaden erleiden bzw. Verbündete um (18.63% der Zaubermacht) Gesundheit geheilt werden, wenn sie durch die Strahlen laufen. Bei Zielen über 5 Ziele hinaus ist der Effekt verringert.\n\nDas Aktivieren von 'Zornige Vergeltung' belegt Verbündete oder Gegner in der Nähe mit bis zu 4 Stapeln 'Morgenlicht'['Zornige Vergeltung' belegt Verbündete oder Gegner in der Nähe mit bis zu 2 Stapeln 'Morgenlicht']['Zornige Vergeltung' belegt Verbündete oder Gegner in der Nähe mit bis zu 4 Stapeln 'Morgenlicht'] und erhöht die Dauer von 'Morgenlicht' um 20%.\n\nDie Heilung von 'Avatar der Sonne' wird nicht auf 'Flamme des Glaubens' übertragen." }
