entries[463746] = { ["name"] = "Honigmarinade", ["text"] = "100 Meter Reichweite\nSofort\nBenk Sumsebrumm überschüttet sein aktuelles Ziel mit brennbarem Honig. Nach 5 Sek. fängt der Spielercharakter Flammen und fügt Spielercharakteren innerhalb von 6 Metern um seinen Standort 4364009 Feuerschaden zu.\n\nBrennender Honig bleibt auf dem Boden und fügt Spielercharakteren innerhalb des Effektbereichs alle 0.5 Sek. 1454670 Feuerschaden zu." }
