entries[463753] = { ["name"] = "Ölflut", ["text"] = "Sofort 4.5 sek. Abklingzeit\nGroße M.A.M.A. speit überschüssiges Öl in einen kegelförmigen Bereich vor sich, das 30 Naturschaden verursacht und die Bewegungsgeschwindigkeit aller Spielercharaktere im Effektbereich 8 Sek. lang um 80% verringert. Die Verlangsamung wird umso größer, je länger sie besteht." }
