entries[463765] = { ["name"] = "Hunger der Kriegsgleve", ["text"] = "Sofort\nVerwüstung\nNach dem Verbrauch eines Seelenfragments verursacht Euer nächster Einsatz von 'Chaosstoß' (40% der Angriffskraft) zusätzlichen Schaden.\n\n'Teufelsklinge' verbraucht bis zu 0 Seelenfragmente in der Nähe.\n\nRachsucht\nNach dem Verbrauch eines Seelenfragments verursacht Euer nächster Einsatz von (40% der Angriffskraft) zusätzlichen Schaden." }
